module bacteria_movement_sim (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] trap_row,\n    input [7:0] trap_col,\n    
    // Bacterium 0 inputs\n    input [7:0] start_row_0,\n    input [7:0] start_col_0,\n    input [1:0] start_dir_0,\n    input [3:0] grid_0 [0:7][0:7],\n    
    // Bacterium 1 inputs\n    input [7:0] start_row_1,\n    input [7:0] start_col_1,\n    input [1:0] start_dir_1,\n    input [3:0] grid_1 [0:7][0:7],\n    
    output reg [15:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] INIT   = 3'd1;\n    localparam [2:0] SIM    = 3'd2;\n    localparam [2:0] CHECK  = 3'd3;\n    localparam [2:0] FINISH = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [7:0] sim_time;\n\n    // Bacterium states\n    reg [7:0] row_0, col_0;\n    reg [1:0] dir_0;\n    reg [7:0] row_1, col_1;\n    reg [1:0] dir_1;\n\n    // Direction encodings\n    localparam [1:0] UP    = 2'd0;\n    localparam [1:0] RIGHT = 2'd1;\n    localparam [1:0] DOWN  = 2'd2;\n    localparam [1:0] LEFT  = 2'd3;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state    <= IDLE;\n            done     <= 1'b0;\n            result   <= 16'd0;\n            sim_time <= 8'd0;\n            row_0    <= 8'd1;\n            col_0    <= 8'd1;\n            dir_0    <= 2'd0;\n            row_1    <= 8'd1;\n            col_1    <= 8'd1;\n            dir_1    <= 2'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) next_state <= INIT;\n                end\n                
                INIT: begin\n                    row_0 <= start_row_0;\n                    col_0 <= start_col_0;\n                    dir_0 <= start_dir_0;\n                    row_1 <= start_row_1;\n                    col_1 <= start_col_1;\n                    dir_1 <= start_dir_1;\n                    sim_time <= 8'd0;\n                    next_state <= SIM;\n                end\n                
                SIM: begin\n                    sim_time <= sim_time + 8'd1;\n\n                    // Update positions based on direction\n                    case (dir_0)\n                        UP:    row_0 <= (row_0 > 8'd1) ? row_0 - 8'd1 : row_0;\n                        RIGHT: col_0 <= (col_0 < 8'd8) ? col_0 + 8'd1 : col_0;\n                        DOWN:  row_0 <= (row_0 < 8'd8) ? row_0 + 8'd1 : row_0;\n                        LEFT:  col_0 <= (col_0 > 8'd1) ? col_0 - 8'd1 : col_0;\n                    endcase\n\n                    case (dir_1)\n                        UP:    row_1 <= (row_1 > 8'd1) ? row_1 - 8'd1 : row_1;\n                        RIGHT: col_1 <= (col_1 < 8'd8) ? col_1 + 8'd1 : col_1;\n                        DOWN:  row_1 <= (row_1 < 8'd8) ? row_1 + 8'd1 : row_1;\n                        LEFT:  col_1 <= (col_1 > 8'd1) ? col_1 - 8'd1 : col_1;\n                    endcase\n                    
                    // Update directions from grid\n                    dir_0 <= (dir_0 + grid_0[row_0-8'd1][col_0-8'd1]) % 4;\n                    dir_1 <= (dir_1 + grid_1[row_1-8'd1][col_1-8'd1]) % 4;\n                    
                    next_state <= CHECK;\n                end\n                
                CHECK: begin\n                    if ((row_0 == trap_row) && (col_0 == trap_col) &&\n                        (row_1 == trap_row) && (col_1 == trap_col)) begin\n                        result <= {8'd0, sim_time};\n                        next_state <= FINISH;\n                    end else if (sim_time == 8'd255) begin\n                        result <= 16'hFFFF;\n                        next_state <= FINISH;\n                    end else begin\n                        next_state <= SIM;\n                    end\n                end\n                
                FINISH: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                
                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule